from .available_devices import SupportedRfSwitchVendors


class RfSwitchFactory:
    @staticmethod
    def _create(vendor, model=None, **kwargs):
        vendors = SupportedRfSwitchVendors()
        rf_switch_device = vendors[vendor][model]
        return rf_switch_device(**kwargs)

    @classmethod
    def create(cls, **kwargs):
        """
        Creates RF switch object.
        Raises DeviceNotSupported.
        """
        if 'rf_switch' in kwargs:
            rf_switch = kwargs.pop('rf_switch')
            rf_switch_dict = {k: v for k, v in vars(rf_switch).items() if v is not None and k not in kwargs}
            kwargs.update(rf_switch_dict)
        return cls._create(**kwargs)
